// =============================================================
// PARSEAR E SCORING — LÓTUS BUSINESS
// Extrai o SCORING_JSON do output do AI Agent e prepara dados
// =============================================================

const output = $json.output || '';

// --- 1. Extrair SCORING_JSON ---
// O prompt instrui colocar SCORING_JSON:{...} na última linha
let scoring = {
  orcamento: false,
  prazo: null,
  decisor: null,
  necessidade: null,
  conhece: false,
  estagio: 'Novo Lead',
  notas: ''
};

const scoringMatch = output.match(/SCORING_JSON:(\{[^{}]+\})/);
if (scoringMatch) {
  try {
    scoring = JSON.parse(scoringMatch[1]);
  } catch(e) {
    // mantém padrão se JSON inválido
  }
}

// --- 2. Limpar texto da resposta (remover linha SCORING_JSON) ---
const textResponse = output
  .replace(/\nSCORING_JSON:\{[^{}]+\}/g, '')
  .replace(/SCORING_JSON:\{[^{}]+\}/g, '')
  .trim();

// --- 3. Dados do trigger Chatwoot ---
const trigger = $('Chatwoot Trigger').first().json;
const conversation = trigger.conversation || {};
const meta = trigger.meta || {};
const sender = meta.sender || {};
const customAttrs = conversation.custom_attributes || {};

// --- 4. Mapeamento estágio → step_id do Kanban ---
const estagioParaStepId = {
  'Novo Lead': 1,
  'Contato Iniciado': 1,
  'Qualificando': 2,
  'Engajado': 3,
  'Proposta Enviada': 4,
  'Negociação': 5,
  'Oportunidade Ganha': 6,
  'Oportunidade Perdida': 7
};

const stepId = estagioParaStepId[scoring.estagio] ?? 1;

// Mover kanban quando scoring foi extraído e estágio avançou
const deveMover = scoringMatch !== null && stepId > 1;

// --- 5. Score numérico 0-100 ---
const score = [
  scoring.orcamento === true,
  scoring.prazo !== null,
  scoring.decisor !== null,
  scoring.necessidade !== null,
  scoring.conhece === true
].filter(Boolean).length * 20;

// --- 6. ID da KanbanTask (salvo em custom_attributes pela criação) ---
const kanbanTaskId = customAttrs.kanban_task_id || null;

// --- 7. Preparar email para HubSpot ---
// WhatsApp leads geralmente não têm email — usar placeholder único
const rawEmail = sender.email || '';
const hasRealEmail = rawEmail.includes('@') && !rawEmail.includes('whatsapp');
const hubspotEmail = hasRealEmail
  ? rawEmail
  : 'wp-conv-' + (conversation.id || 'unknown') + '@lotus-lead.local';

return {
  textResponse,
  conversationId: String(conversation.id || ''),
  contactEmail: rawEmail,
  hubspotEmail,
  contactName: sender.name || 'Lead WhatsApp',
  contactPhone: sender.phone_number || '',
  deveMover,
  stepId,
  estagioFinal: scoring.estagio,
  score,
  notas: scoring.notas || '',
  kanbanTaskId,
  scoringOrcamento: scoring.orcamento,
  scoringPrazo: scoring.prazo,
  scoringDecisor: scoring.decisor,
  scoringNecessidade: scoring.necessidade
};

// TODO: Buscar no HubSpot leads com status 'Qualificando'
// que não responderam nas últimas 24h e enviar follow-up
// por enquanto retorna vazio para não disparar mensagens
return [];
